import React from 'react';
import { Link } from 'react-router-dom';
import MotionReveal from '../../motion/MotionReveal.jsx';
import OutlineIcon from '../icons/OutlineIcon.jsx';
import './TransformationBanner.css';

const SLIDE_CARDS = [
  {
    to: '/career-assessment',
    icon: 'compass',
    title: 'Career assessment',
    text: 'Map aptitude and interest to a stream.',
    image: '/images/hero-1-desktop.webp',
  },
  {
    to: '/kcet-predictor',
    icon: 'cap',
    title: 'KCET predictor',
    text: 'Safe, moderate and dream colleges.',
    image: '/images/hero-2-desktop.webp',
  },
  {
    to: '/pgcet-predictor',
    icon: 'book',
    title: 'PGCET predictor',
    text: 'Postgraduate matches by rank.',
    image: '/images/hero-3-desktop.webp',
  },
  {
    to: '/college-compare',
    icon: 'scale',
    title: 'Compare colleges',
    text: 'Fees, courses and rankings side by side.',
    image: '/images/student-to-professional.png',
  },
  {
    to: '/college-admission-enquiry',
    icon: 'handshake',
    title: 'Admission support',
    text: 'Counsellor follow-through until you join.',
    image: '/images/hero-journey.png',
  },
];

function SlideCard({ card }) {
  return (
    <Link to={card.to} className="mmc-slide-card">
      <img src={card.image} alt="" />
      <span className="mmc-slide-icon">
        <OutlineIcon name={card.icon} size={16} />
      </span>
      <strong>{card.title}</strong>
      <small>{card.text}</small>
    </Link>
  );
}

export default function TransformationBanner() {
  const loop = [...SLIDE_CARDS, ...SLIDE_CARDS];

  return (
    <section className="mmc-transform section">
      <div className="container mmc-transform-inner">
        <MotionReveal strong className="mmc-exist">
          <p className="mmc-section-eyebrow">Why we exist</p>
          <h2>
            Every student carries
            {' '}
            <span className="mmc-mark">unique talent, hard-won effort,</span>
            {' '}
            and a career waiting to be mapped.
          </h2>
          <p>
            MapMyCareer360 turns confusion into a clear plan — assessment, college prediction,
            and admission support without the noise.
          </p>
          <div className="mmc-exist-person">
            <img src="/images/logo.png" alt="" />
            <div>
              <strong>Counselling team</strong>
              <span>Bangalore · MapMyCareer360</span>
            </div>
          </div>
          <Link to="/career-assessment" className="btn btn-ink">Start your transformation</Link>
        </MotionReveal>

        <MotionReveal delay={120} className="mmc-transform-slider" aria-label="Guidance tools">
          <div className="mmc-slide-track">
            {loop.map((card, i) => (
              <SlideCard key={`${card.to}-${i}`} card={card} />
            ))}
          </div>
        </MotionReveal>
      </div>
    </section>
  );
}
